<template>
<div class="sync-page">
 <header class="sync-header"><div><span class="eyebrow">ATLAS · PROCUREMENT LEADERSHIP</span><h1>PROCUREMENT WEEKLY SYNC</h1><p>{{ longDate }}</p></div><div class="sync-tools"><button class="primary" @click="startMeeting"><Play :size="16"/> Start Weekly Sync</button><label class="search"><Search :size="16"/><input v-model="filters.search" placeholder="Search projects, POs, vendors, parts, notes…"/></label></div></header>
 <section class="kpi-strip"><button v-for="k in kpis" :key="k.label" :class="{selected:quick===k.filter}" @click="quick=quick===k.filter?'All':k.filter"><span>{{ k.label }}</span><b>{{ k.money?currency(k.value):k.value }}</b></button></section>
 <section class="last-actions"><div><span>ACTIONS FROM LAST MEETING</span><strong>{{ actionCounts.total }} Actions</strong></div><button @click="actionFilter='Complete'">{{actionCounts.complete}} Complete</button><button @click="actionFilter='Open'">{{actionCounts.open}} Open</button><button class="danger" @click="actionFilter='Overdue'">{{actionCounts.overdue}} Overdue</button></section>
 <div class="sticky-controls"><div class="quick"><button v-for="q in quickFilters" :key="q" :class="{active:quick===q}" @click="quick=q">{{q}}</button></div><div class="filters"><select v-model="filters.lead"><option value="">All Leads</option><option v-for="u in owners" :value="u.id" :key="u.id">{{u.name}}</option></select><select v-model="filters.customer"><option value="">All Customers</option><option v-for="c in customers" :key="c">{{c}}</option></select><select v-model="filters.phase"><option value="">All Phases</option><option v-for="p in phases" :key="p">{{p}}</option></select><select v-model="filters.health"><option value="">All Statuses</option><option v-for="s in healths" :key="s">{{s}}</option></select><select v-model="filters.aging"><option value="">Any Age</option><option>0–7</option><option>8–14</option><option>15–30</option><option>30+</option></select><button @click="advanced=!advanced"><SlidersHorizontal :size="15"/> Filters</button></div><nav><button v-for="v in views" :key="v" :class="{active:view===v}" @click="view=v">{{v}}</button></nav></div>
 <section v-if="advanced" class="advanced"><label>Project Manager<input v-model="filters.pm"/></label><label>Vendor<input v-model="filters.vendor"/></label><label>Due before<input v-model="filters.due" type="date"/></label><label>Updated since<input v-model="filters.updated" type="date"/></label><button @click="clearFilters">Clear filters</button></section>
 <p class="result-meta">{{visible.length}} of {{rows.length}} active procurements · {{currency(visible.reduce((n,r)=>n+r.value,0))}}</p>

 <section v-if="view==='BOARD'" class="board"><article v-for="phase in phases" :key="phase" class="column"><header><div><b>{{phase}}</b><span>{{byPhase(phase).length}} · {{currency(byPhase(phase).reduce((n,r)=>n+r.value,0))}}</span></div></header><div class="card-stack" @dragover.prevent @drop="dropPhase(phase)"><button v-for="r in byPhase(phase)" :key="r.project.id" class="proc-card" draggable="true" @dragstart="dragId=r.project.id" @click="open(r)"><div class="card-head"><span>{{r.project.projectNumber}}</span><i :class="healthClass(r.health)">{{r.health}}</i></div><h3>{{r.project.projectName}}</h3><p>{{r.project.customer}}</p><div class="card-phase"><span :style="{width:r.progress+'%'}"></span></div><dl><div><dt>Lead</dt><dd>{{r.lead}}</dd></div><div><dt>Value</dt><dd>{{currency(r.value)}}</dd></div><div><dt>Next</dt><dd>{{r.nextAction}}</dd></div><div><dt>Owner / Due</dt><dd>{{r.nextOwner}} · {{r.dueDate?shortDate(r.dueDate):'No date'}}</dd></div></dl><p v-if="r.latestNote" class="note">{{r.latestNote.text}}</p><footer><span>{{r.daysInPhase}}d in phase</span><span v-if="r.openActions">{{r.openActions}} actions</span><span v-if="r.discussion" class="discuss"><MessageSquare :size="12"/> Discuss</span><span v-if="r.vendorException" class="exception"><TriangleAlert :size="12"/> Exception</span></footer></button></div></article></section>

 <section v-else-if="view==='LIST'" class="table-wrap"><table><thead><tr><th @click="sort='project'">Project</th><th>Customer</th><th>Lead / PM</th><th>Phase</th><th>Status</th><th>Value</th><th>Age</th><th>Next Action</th><th>Due</th><th>Flags</th><th>Updated</th></tr></thead><tbody><tr v-for="r in visible" :key="r.project.id" @click="open(r)"><td><b>{{r.project.projectNumber}}</b><span>{{r.project.projectName}}</span></td><td>{{r.project.customer}}</td><td>{{r.lead}}<span>{{r.pm}}</span></td><td>{{r.phase}}</td><td><i :class="healthClass(r.health)">{{r.health}}</i></td><td>{{currency(r.value)}}</td><td>{{r.daysInPhase}}d</td><td>{{r.nextAction}}<span>{{r.nextOwner}}</span></td><td>{{r.dueDate?shortDate(r.dueDate):'—'}}</td><td>{{r.discussion?'Discuss ':''}}{{r.vendorException?'Exception':''}}</td><td>{{r.project.updatedAt?shortDate(r.project.updatedAt):'—'}}</td></tr></tbody></table></section>

 <section v-else-if="view==='TIMELINE'" class="timeline"><header><h2>Procurement Timeline</h2><div><button v-for="z in ['Week','Month','Quarter']" :class="{active:zoom===z}" @click="zoom=z">{{z}}</button></div></header><div class="timeline-scale"><span v-for="p in phases" :key="p">{{p.replace(' / ','/')}}</span></div><button v-for="r in visible" :key="r.project.id" class="timeline-row" @click="open(r)"><b>{{r.project.projectNumber}}<small>{{r.project.projectName}}</small></b><div><i :style="{width:(r.progress+7)+'%'}"></i><em :style="{left:r.progress+'%'}">{{r.phase}}</em></div></button><p class="timeline-note">Bars reflect verified phase progression. Milestone dates are only shown when present in Atlas.</p></section>

 <section v-else class="meeting-list"><header><div><span>ITEMS REQUIRING DISCUSSION</span><h2>{{meetingMode?meetingSections[meetingSection]:'Meeting Priorities'}}</h2></div><div v-if="meetingMode"><button @click="meetingSection=Math.max(0,meetingSection-1)"><ChevronLeft :size="15"/> Previous</button><b>{{meetingSection+1}} / {{meetingSections.length}}</b><button @click="meetingSection=Math.min(meetingSections.length-1,meetingSection+1)">Next <ChevronRight :size="15"/></button></div></header><table><thead><tr><th>Status</th><th>Project</th><th>Issue / Discussion Reason</th><th>Phase</th><th>Lead</th><th>Next Action</th><th>Due</th><th>Waiting</th></tr></thead><tbody><tr v-for="r in meetingRows" :key="r.project.id" @click="open(r)"><td><i :class="healthClass(r.health)">{{r.health}}</i></td><td><b>{{r.project.projectNumber}}</b><span>{{r.project.projectName}}</span></td><td>{{r.discussion?.reason||r.healthReason}}</td><td>{{r.phase}}</td><td>{{r.lead}}</td><td>{{r.nextAction}}</td><td>{{r.dueDate?shortDate(r.dueDate):'—'}}</td><td>{{r.daysInPhase}}d</td></tr></tbody></table></section>

 <div v-if="selected" class="drawer-shade" @click.self="selected=null"><aside class="drawer"><header><div><span>{{selected.project.projectNumber}}</span><h2>{{selected.project.projectName}}</h2><p>{{selected.project.customer}}</p></div><button @click="selected=null"><X/></button></header><div class="drawer-body"><section class="drawer-summary"><div><span>Status</span><select :value="selected.health" @change="overrideHealth(($event.target as HTMLSelectElement).value as ProcurementHealth)"><option v-for="s in healths">{{s}}</option></select></div><div><span>Phase</span><select :value="selected.phase" @change="overridePhase(($event.target as HTMLSelectElement).value as ProcurementPhase)"><option v-for="p in phases">{{p}}</option></select></div><div><span>Progress</span><b>{{selected.progress}}%</b></div><div><span>Days in phase</span><b>{{selected.daysInPhase}}</b></div><div><span>Procurement lead</span><b>{{selected.lead}}</b></div><div><span>Project manager</span><b>{{selected.pm}}</b></div><div><span>Active value</span><b>{{currency(selected.value)}}</b></div><div><span>Due date</span><b>{{selected.dueDate?shortDate(selected.dueDate):'Not set'}}</b></div></section><section class="issue"><span>Current issue</span><b>{{selected.discussion?.reason||selected.healthReason}}</b><p>Next: {{selected.nextAction}} · {{selected.nextOwner}}</p></section><section v-if="selected.changes.length"><h3>SINCE LAST MEETING</h3><ul><li v-for="c in selected.changes" :key="c">{{c}}</li></ul></section><section><div class="section-title"><h3>DISCUSSION</h3><button v-if="selected.discussion" @click="resolveDiscussion">Resolve</button></div><p v-if="selected.discussion">Flagged by {{selected.discussion.flaggedByName}} · {{selected.discussion.reason}}</p><form v-else @submit.prevent="flagDiscussion"><input v-model="discussionReason" placeholder="Reason for weekly discussion" required/><button>Flag</button></form></section><section><div class="section-title"><h3>OPEN ACTIONS</h3><button @click="showAction=!showAction">+ Add Action</button></div><article v-for="a in projectActions" :key="a.id" class="action-row"><button @click="completeAction(a)">{{a.status==='Complete'?'✓':'○'}}</button><div><b>{{a.description}}</b><span>{{a.ownerName}} · {{a.dueDate?shortDate(a.dueDate):'No due date'}} · {{a.priority}}</span></div></article><form v-if="showAction" class="entry-form" @submit.prevent="addAction"><input v-model="actionDraft.description" placeholder="Action description" required/><select v-model="actionDraft.ownerId" required><option value="">Owner</option><option v-for="u in owners" :value="u.id">{{u.name}}</option></select><input v-model="actionDraft.dueDate" type="date" required/><select v-model="actionDraft.priority"><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select><button>Add Action</button></form></section><section><div class="section-title"><h3>WEEKLY NOTES</h3><button @click="showNote=!showNote">+ Add Note</button></div><form v-if="showNote" @submit.prevent="addNote"><textarea v-model="noteDraft" placeholder="Capture a durable meeting note…" required></textarea><button>Add Note</button></form><article v-for="n in projectNotes" :key="n.id" class="history"><b>{{shortDate(n.createdAt)}} · {{n.createdByName}}</b><p>{{n.text}}</p></article></section><section><h3>PROCUREMENT DETAIL</h3><dl class="detail-list"><div><dt>Purchase orders</dt><dd>{{selected.project.purchaseOrders.length}}</dd></div><div><dt>Shipping</dt><dd>{{selected.project.shipmentStatus||'Not started'}}</dd></div><div><dt>Receiving</dt><dd>{{receiving(selected.project)}}</dd></div><div><dt>Open actions</dt><dd>{{selected.openActions}}</dd></div></dl></section></div><footer><button @click="markDiscussed">Mark Discussed</button><RouterLink class="primary" :to="`/projects/${selected.project.id}`">Open Full Project <ExternalLink :size="14"/></RouterLink></footer></aside></div>
</div>
</template>

<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref} from 'vue';import{ChevronLeft,ChevronRight,ExternalLink,MessageSquare,Play,Search,SlidersHorizontal,TriangleAlert,X}from'@lucide/vue';import{fetchSession,loadUsers}from'../../services/auth';import{loadProjects}from'../../services/localProjects';import type{Project,UserProfile}from'../../types';import{PROCUREMENT_PHASES,agingBucket,buildRows,hydrateWeeklyState,isOverdue,loadWeeklyState,makeSnapshot,saveWeeklyState,type ProcurementAction,type ProcurementHealth,type ProcurementPhase,type ProcurementRow}from'../../services/weeklyProcurement';
type View='BOARD'|'LIST'|'TIMELINE'|'MEETING';const phases=PROCUREMENT_PHASES,healths:ProcurementHealth[]=['On Track','Attention','Critical','On Hold','Complete'],views:View[]=['BOARD','LIST','TIMELINE','MEETING'],quickFilters=['All','Needs Attention','Critical','Overdue','Awaiting Vendor','Awaiting Customer','Shipping','This Week','Needs Discussion'];const projects=ref<Project[]>(loadProjects()),users=ref<UserProfile[]>(loadUsers()),state=ref(loadWeeklyState()),view=ref<View>('BOARD'),quick=ref('All'),advanced=ref(false),zoom=ref('Month'),sort=ref(''),dragId=ref(''),selected=ref<ProcurementRow|null>(null),meetingMode=ref(false),meetingSection=ref(0),actionFilter=ref(''),discussionReason=ref(''),showAction=ref(false),showNote=ref(false),noteDraft=ref(''),actionDraft=reactive({description:'',ownerId:'',dueDate:'',priority:'Medium' as ProcurementAction['priority']}),filters=reactive({search:'',lead:'',customer:'',phase:'',health:'',aging:'',pm:'',vendor:'',due:'',updated:''});const session=computed(()=>fetchSession()),rows=computed(()=>buildRows(projects.value,users.value,state.value)),owners=computed(()=>users.value.filter(u=>u.active)),customers=computed(()=>[...new Set(rows.value.map(r=>r.project.customer).filter(Boolean))].sort()),longDate=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date());
const visible=computed(()=>rows.value.filter(r=>{const q=filters.search.trim().toLowerCase(),vendor=filters.vendor.toLowerCase(),thisWeek=r.dueDate&&new Date(r.dueDate).getTime()<=Date.now()+7*864e5;return(!q||r.searchText.includes(q))&&(!filters.lead||r.leadId===filters.lead)&&(!filters.customer||r.project.customer===filters.customer)&&(!filters.phase||r.phase===filters.phase)&&(!filters.health||r.health===filters.health)&&(!filters.aging||agingBucket(r.daysInPhase)===filters.aging)&&(!filters.pm||r.pm.toLowerCase().includes(filters.pm.toLowerCase()))&&(!vendor||r.searchText.includes(vendor))&&(!filters.due||!r.dueDate||r.dueDate<=filters.due)&&(!filters.updated||r.project.updatedAt&&r.project.updatedAt>=filters.updated)&&(quick.value==='All'||quick.value==='Needs Attention'&&['Attention','Critical'].includes(r.health)||quick.value==='Critical'&&r.health==='Critical'||quick.value==='Overdue'&&state.value.actions.some(a=>a.projectId===r.project.id&&isOverdue(a))||quick.value==='Awaiting Vendor'&&r.vendorException||quick.value==='Awaiting Customer'&&r.phase==='Customer Approval / Funding'||quick.value==='Shipping'&&r.phase==='Shipping'||quick.value==='This Week'&&thisWeek||quick.value==='Needs Discussion'&&!!r.discussion)}));
const actionCounts=computed(()=>{const a=state.value.actions;return{total:a.length,complete:a.filter(x=>x.status==='Complete').length,open:a.filter(x=>!['Complete','Cancelled'].includes(x.status)).length,overdue:a.filter(x=>isOverdue(x)).length}}),kpis=computed(()=>[{label:'Active Procurements',value:rows.value.filter(r=>r.phase!=='Complete').length,filter:'All'},{label:'Total Active Value',value:rows.value.filter(r=>r.phase!=='Complete').reduce((n,r)=>n+r.value,0),filter:'All',money:true},{label:'Needs Attention',value:rows.value.filter(r=>r.health==='Attention').length,filter:'Needs Attention'},{label:'Critical',value:rows.value.filter(r=>r.health==='Critical').length,filter:'Critical'},{label:'Overdue Actions',value:actionCounts.value.overdue,filter:'Overdue'},{label:'Awaiting Pricing',value:rows.value.filter(r=>r.phase==='Pricing / RFQ').length,filter:'All'},{label:'Awaiting Approval',value:rows.value.filter(r=>r.phase==='Customer Approval / Funding').length,filter:'Awaiting Customer'},{label:'Ordered',value:rows.value.filter(r=>r.phase==='Ordered').length,filter:'All'},{label:'Shipping',value:rows.value.filter(r=>r.phase==='Shipping').length,filter:'Shipping'},{label:'Receiving / Kitting',value:rows.value.filter(r=>['Receiving','Kitting / Staging'].includes(r.phase)).length,filter:'All'}]),meetingSections=['Overdue actions','Critical procurements','Needs Discussion','Attention items','Stalled procurements','Major changes since last meeting','Remaining active procurements'],meetingRows=computed(()=>{const base=visible.value;if(!meetingMode.value)return[...base].sort(prioritySort);return base.filter(r=>[state.value.actions.some(a=>a.projectId===r.project.id&&isOverdue(a)),r.health==='Critical',!!r.discussion,r.health==='Attention',r.stalled,r.changes.length>0,r.phase!=='Complete'][meetingSection.value])}),projectActions=computed(()=>state.value.actions.filter(a=>a.projectId===selected.value?.project.id).sort((a,b)=>Number(a.status==='Complete')-Number(b.status==='Complete')||a.dueDate.localeCompare(b.dueDate))),projectNotes=computed(()=>state.value.notes.filter(n=>n.projectId===selected.value?.project.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)));
function refresh(){projects.value=loadProjects();users.value=loadUsers();state.value=loadWeeklyState();if(selected.value)selected.value=rows.value.find(r=>r.project.id===selected.value?.project.id)||null}onMounted(()=>{void hydrateWeeklyState().then(refresh);window.addEventListener('cronos:projects-changed',refresh);window.addEventListener('atlas:weekly-procurement-changed',refresh)});onUnmounted(()=>{window.removeEventListener('cronos:projects-changed',refresh);window.removeEventListener('atlas:weekly-procurement-changed',refresh)});function persist(){saveWeeklyState(state.value);refresh()}function byPhase(p:ProcurementPhase){return visible.value.filter(r=>r.phase===p)}function open(r:ProcurementRow){selected.value=r;discussionReason.value='';showAction.value=false;showNote.value=false}function healthClass(h:string){return`health ${h.toLowerCase().replaceAll(' ','-')}`}function currency(v:number){return new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v)}function shortDate(v:string){return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(v))}function prioritySort(a:ProcurementRow,b:ProcurementRow){return healths.indexOf(b.health)-healths.indexOf(a.health)||Number(!!b.discussion)-Number(!!a.discussion)||b.daysInPhase-a.daysInPhase}function startMeeting(){view.value='MEETING';meetingMode.value=true;meetingSection.value=0;const s=session.value;if(s){state.value.snapshots=[...state.value.snapshots,makeSnapshot(rows.value,s)].slice(-12);persist()}}function clearFilters(){Object.assign(filters,{search:'',lead:'',customer:'',phase:'',health:'',aging:'',pm:'',vendor:'',due:'',updated:''});quick.value='All'}
function overridePhase(phase:ProcurementPhase){if(!selected.value||!session.value)return;state.value.overrides=state.value.overrides.filter(o=>o.projectId!==selected.value!.project.id);state.value.overrides.push({projectId:selected.value.project.id,phase,phaseEnteredAt:new Date().toISOString(),health:selected.value.health,updatedBy:session.value.id,updatedAt:new Date().toISOString(),reason:'Manual phase override'});persist()}function overrideHealth(health:ProcurementHealth){if(!selected.value||!session.value)return;const old=state.value.overrides.find(o=>o.projectId===selected.value!.project.id);state.value.overrides=state.value.overrides.filter(o=>o.projectId!==selected.value!.project.id);state.value.overrides.push({...old,projectId:selected.value.project.id,health,phase:old?.phase||selected.value.phase,updatedBy:session.value.id,updatedAt:new Date().toISOString(),reason:`Manual status override from ${selected.value.health}`});persist()}function dropPhase(p:ProcurementPhase){const r=rows.value.find(x=>x.project.id===dragId.value);if(r){selected.value=r;overridePhase(p);selected.value=null}dragId.value=''}
function flagDiscussion(){if(!selected.value||!session.value)return;state.value.discussions.push({id:crypto.randomUUID(),projectId:selected.value.project.id,reason:discussionReason.value,flaggedBy:session.value.id,flaggedByName:session.value.name,flaggedAt:new Date().toISOString()});discussionReason.value='';persist()}function resolveDiscussion(){const d=selected.value?.discussion,s=session.value;if(!d||!s)return;d.resolvedAt=new Date().toISOString();d.resolvedBy=s.id;persist()}function markDiscussed(){if(selected.value?.discussion)resolveDiscussion();if(meetingMode.value)meetingSection.value=Math.min(meetingSections.length-1,meetingSection.value+1)}function addNote(){const s=session.value,r=selected.value;if(!s||!r)return;state.value.notes.push({id:crypto.randomUUID(),projectId:r.project.id,text:noteDraft.value,createdBy:s.id,createdByName:s.name,createdAt:new Date().toISOString(),meetingDate:meetingMode.value?new Date().toISOString().slice(0,10):undefined,type:meetingMode.value?'Weekly Sync':'General'});noteDraft.value='';showNote.value=false;persist()}function addAction(){const s=session.value,r=selected.value,u=users.value.find(x=>x.id===actionDraft.ownerId);if(!s||!r||!u)return;state.value.actions.push({id:crypto.randomUUID(),projectId:r.project.id,description:actionDraft.description,ownerId:u.id,ownerName:u.name,assignedBy:s.id,assignedByName:s.name,assignedAt:new Date().toISOString(),dueDate:actionDraft.dueDate,status:'Open',priority:actionDraft.priority,meetingDate:meetingMode.value?new Date().toISOString().slice(0,10):undefined});Object.assign(actionDraft,{description:'',ownerId:'',dueDate:'',priority:'Medium'});showAction.value=false;persist()}function completeAction(a:ProcurementAction){a.status=a.status==='Complete'?'Open':'Complete';a.completedAt=a.status==='Complete'?new Date().toISOString():undefined;persist()}function receiving(p:Project){const l=p.purchaseOrders.flatMap(x=>x.lines),o=l.reduce((n,x)=>n+x.quantityOrdered,0),r=l.reduce((n,x)=>n+x.quantityReceived,0);return o?`${r} of ${o} items received`:'No receiving records'}
</script>

